/// <summary>
/// The service class for the batch job
/// </summary>
class METBackOrderProcessingService extends SysOperationServiceBase
{
}

Method.Source:
    /// <summary>
    /// The process method for the back orders processing
    /// </summary>
    /// <param name = "_contract">The data contract object</param>
    public void processOperation(METBackOrderProcessingDataContract _contract)
    {
        Query query;
        QueryRun queryRun;
        QueryBuildDataSource qbdsPurchTable;
        QueryBuildDataSource qbdsMetPurchTable;
        
        InventSite inventSite;
        PurchTable purchTable;
        PurchLine purchLine;
        METPurchLine metPurchLine;
        METPurchTable metPurchTable;
        VendPackingSlipJour vendPackingSlipJour;        
        METBackOrderPurchLineTmp metBackOrderPurchLineTmp;

        utcdatetime currentDateTime = DateTimeUtil::applyTimeZoneOffset(DateTimeUtil::getSystemDateTime(), DateTimeUtil::getUserPreferredTimezone());
        
        date startDate; 
        date endDate =  DateTimeUtil::date(currentDateTime);
        int totalDays;
        
        query = _contract.getQuery();
        
        qbdsPurchTable = query.dataSourceTable(tableNum(InventSite)).addDataSource(tableNum(PurchTable));
        qbdsPurchTable.relations(true);
        qbdsPurchTable.joinMode(JoinMode::InnerJoin);
        qbdsPurchTable.addRange(fieldNum(PurchTable, PurchStatus)).value(queryValue(PurchStatus::Backorder));
        
        qbdsMetPurchTable = qbdsPurchTable.addDataSource(tableNum(MetPurchTable));
        qbdsMetPurchTable.relations(true);
        qbdsMetPurchTable.joinMode(JoinMode::InnerJoin);
        qbdsMetPurchTable.addRange(fieldNum(METPurchTable, POBackOrderSetting)).value(queryValue(NoYes::No));
        
        queryRun = new QueryRun(query);

        while (queryRun.next())
        {
            inventSite = null;
            purchTable = null;
            vendPackingSlipJour = null;
            
            inventSite = queryRun.get(tableNum(InventSite));
            purchTable = queryRun.get(tableNum(PurchTable));            
            select maxOf(DeliveryDate) from vendPackingSlipJour
                where vendPackingSlipJour.PurchId == purchTable.PurchId;

            if (vendPackingSlipJour.DeliveryDate)
            {
                startDate = vendPackingSlipJour.DeliveryDate;
                totalDays = endDate - startDate; //Calculate number of days from today to last posted product receipt including weekends.
                    
                if (!_contract.parmIncludeWeekends())
                {                        
                    totalDays = 0;

                    //Calculate number of days from today to last posted product receipt excluding weekends.
                    while (startDate < endDate)
                    {
                        int dayNumber = dayOfWk(startDate);
                        if (dayNumber == 6 || dayNumber == 7) // Saturday or Sunday
                        {
                            startDate++;
                            continue;
                        }
                            
                        totalDays++;
                        startDate++;
                    }
                }

                if (totalDays >= inventSite.METPOBackOrderBatchJobDays)
                {   
                    ttsbegin;

                    // Hold Order Qty and Amount in a temp table.
                    insert_recordset metBackOrderPurchLineTmp (PurchId, PurchQty, LineAmount, PurchLineRecId)
                        select PurchId, PurchQty, LineAmount, RecId from purchLine
                            where purchLine.PurchId == purchTable.PurchId;

                    // Cancel PO lines.
                    PurchCancel purchCancel = PurchCancel::METConstruct();
                    purchCancel.parmMetPurchTable(purchTable);
                    purchCancel.run();                       
                    
                    // Restore Order Qty and Amount from temp table.
                    purchLine.skipDataMethods(true);
                    update_recordset purchLine setting 
                        purchQty = metBackOrderPurchLineTmp.PurchQty, 
                        LineAmount = metBackOrderPurchLineTmp.LineAmount
                        where purchLine.PurchId == purchTable.PurchId
                    join metBackOrderPurchLineTmp
                        where metBackOrderPurchLineTmp.PurchLineRecId == metPurchLine.purchLine;

                    // Update integration status for PO lines
                    metPurchLine.skipDataMethods(true);
                    update_recordset metPurchLine setting
                        IntegrationStatus = METIntegrationStatus::ReadyToSend 
                    join metBackOrderPurchLineTmp
                        where metBackOrderPurchLineTmp.PurchLineRecId == metPurchLine.purchLine;

                    // Update integration status for PO header
                    metPurchTable = METPurchTable::findByPurchTable(purchTable.RecId, true);
                    metPurchTable.doUpdateIntegrationStatus(METIntegrationStatus::ReadyToSend);

                    // Confirm PO
                    this.confirmPO(purchTable);

                    // Empty temp table
                    delete_from metBackOrderPurchLineTmp
                        where metBackOrderPurchLineTmp.PurchId == purchTable.PurchId;

                    ttscommit;
                }
            }            
        }
    }

    /// <summary>
    /// Confirms the Purchase Order
    /// </summary>
    /// <param name = "_purchTable">The Purchase Order record buffer to be confirmed.</param>
    private void confirmPO(PurchTable _purchTable)
    {   
        METVersioningPurchaseOrder                  versioningPurchaseOrder;

        _purchTable.reread(); // Re-read after PO cancellation
        if (_purchTable.ChangeRequestRequired)
        {
            versioningPurchaseOrder = METVersioningPurchaseOrder::newPurchaseOrder(PurchTable::find(_purchTable.PurchId));
            if (_purchTable.canSubmitToWorkflow())
            {
                versioningPurchaseOrder.submitChangeRequest();
                versioningPurchaseOrder.approveChangeRequest();
            }
        }

        _purchTable.reread(); // Re-read after workflow change request approval
        if (_purchTable.DocumentState == VersioningDocumentState::Approved
            && _purchTable.ChangeRequestRequired)
        {
            versioningPurchaseOrder.confirm();
        }
    }
